import React, { useState } from 'react';
import Table from './components/Table';
import './App.css';

function App() {
    const [tables, setTables] = useState([]);
    const [selectedTable, setSelectedTable] = useState(null);

    const addTable = () => {
        const newTableId = tables.length + 1;
        setTables(prevTables => [...prevTables, newTableId]);
        setSelectedTable(newTableId);
    };

    const selectTable = (tableId) => {
        setSelectedTable(tableId);
    };

    return (
        <div className="App">
            <div className="sidebar">
                <button className="add-table-btn" onClick={addTable}>Add Table</button>
                <div className="table-list">
                    {tables.map(tableId => (
                        <div 
                            key={tableId} 
                            className={`table-item ${selectedTable === tableId ? 'active' : ''}`}
                            onClick={() => selectTable(tableId)}
                        >
                            Table {tableId}
                        </div>
                    ))}
                </div>
            </div>
            <div className="main-content">
                {selectedTable && <Table tableId={selectedTable} />}
            </div>
        </div>
    );
}

export default App;
